// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2);
        try c.Deposit{value: amount1}() {} catch { return; }
        uint256 balAfterFirst;
        try c.balances(address(this)) returns (uint256 __r) { balAfterFirst = __r; } catch { return; }
        try c.Deposit{value: amount2}() {} catch { return; }
        uint256 balAfterSecond;
        try c.balances(address(this)) returns (uint256 __r) { balAfterSecond = __r; } catch { return; }
        assertTrue(balAfterSecond >= balAfterFirst && balAfterSecond - balAfterFirst == amount2);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
